<?php
declare(strict_types=1);
require __DIR__ . '/config.php';
$config = ['site' => rtrim(dirname($_SERVER['SCRIPT_NAME'] ?? '/'), '/\\'), 'pollMs' => 1000, 'maxDepthCm' => 25, 'warningDepthCm' => 18, 'dangerDepthCm' => 22];
$rows = [];
$dbOnline = false;
$now = new DateTimeImmutable();
try {
    $rows = database()->query('SELECT id, water_level_cm, distance_cm, temperature_c, humidity_pct, rain_detected, rain_probability_pct, alert_level, recorded_at FROM sensor_readings ORDER BY recorded_at DESC, id DESC LIMIT 1000')->fetchAll();
    $dbOnline = true;
} catch (Throwable $error) {
    error_log('Flood monitor water level page unavailable: ' . $error->getMessage());
}
$demo = !$rows;
if ($demo) {
    for ($i = 17; $i >= 0; $i--) {
        $minutesAgo = $i * 2;
        $water = round(16.4 - $i * .054 + sin($i * .82) * .12, 1);
        $rows[] = ['id' => 1842 - (17 - $i), 'water_level_cm' => max(0, $water), 'distance_cm' => round(max(0, 25 - $water), 1), 'temperature_c' => 29.4, 'humidity_pct' => 82, 'rain_detected' => $i > 3 ? 1 : 0, 'rain_probability_pct' => 34, 'alert_level' => 'warning', 'recorded_at' => $now->modify("-{$minutesAgo} minutes")->format('Y-m-d H:i:s')];
    }
} else {
    $rows = array_reverse($rows);
}
$latestRecord = $dbOnline && !$demo ? $rows[array_key_last($rows)] : null;
$deviceOnline = $latestRecord && abs(time() - (new DateTimeImmutable((string)$latestRecord['recorded_at']))->getTimestamp()) <= 10;
$chartRows = array_slice($rows, -18);
$chartTimes = array_map(static fn ($row) => (new DateTimeImmutable((string)$row['recorded_at']))->format('H:i'), $chartRows);
$latest = $rows ? $rows[array_key_last($rows)] : null;
$latestLevel = $latest ? number_format((float)$latest['water_level_cm'], 1) : '—';
$latestAt = $latest ? (new DateTimeImmutable((string)$latest['recorded_at']))->format('H:i:s') : '—';
?>
